const TURKEY_CITIES='adana adiyaman afyonkarahisar agri amasya ankara antalya artvin aydin balikesir bilecik bingol bitlis bolu burdur bursa canakkale cankiri corum denizli diyarbakir edirne elazig erzincan erzurum eskisehir gaziantep giresun gumushane hakkari hatay isparta mersin istanbul izmir kars kastamonu kayseri kirklareli kirsehir kocaeli konya kutahya malatya manisa kahramanmaras mardin mugla mus nevsehir nigde ordu rize sakarya samsun siirt sinop sivas tekirdag tokat trabzon tunceli sanliurfa usak van yozgat zonguldak aksaray bayburt karaman kirikkale batman sirnak bartin ardahan igdir yalova karabuk kilis osmaniye duzce'.split(' ');
function nationalText(value){return String(value||'').toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').replace(/[’']/g,' ').replace(/[^a-z0-9., ]/g,' ').replace(/\s+/g,' ').trim()}
function casualtyCount(text,kind){const words={bir:1,iki:2,uc:3,dort:4,bes:5,alti:6,yedi:7,sekiz:8,dokuz:9,on:10,yirmi:20,otuz:30,elli:50,yuz:100};const numbers='(\\d+|'+Object.keys(words).join('|')+')';const outcome=kind==='dead'?'(?:olu|oldu|hayatini kaybetti|can kaybi|yasamini yitirdi)':kind==='injured'?'(?:yarali|yaralandi|zehirlendi)':'(?:tahliye edildi|tahliye ediliyor|tahliye edilecek|mahsur|enkaz altinda)';let max=0;for(const m of text.matchAll(new RegExp('(?:^| )'+numbers+'(?:\\s+(?:kisi|kisinin|yolcu|isci|asker|polis|vatandas|ogrenci|kisiye|kiside)){0,2}\\s+'+outcome,'g')))max=Math.max(max,Number(m[1])||words[m[1]]||0);return max}
export function nationalCritical(title,description=''){
 const h=nationalText(title),text=nationalText(title+' '+description),city=TURKEY_CITIES.find(c=>new RegExp('(?:^| )'+c+'(?:da|de|dan|den|nin|nun)?(?: |$)').test(text));
 const explicitTurkey=/\b(?:turkiye|turkiyede|turkiyenin|turk|tsk|msb|jandarma)\b|askerimiz|polisimiz|personelimiz|sehitlerimiz|vatandasimiz|vatandaslarimiz|pence kilit|pence kaplan|pence simsek/.test(text);
 const linkedAbroad=/turk (?:asker|personel|vatandas|buyukelcil|konsolos|silahli|helikopter|ucak)|askerimiz|personelimiz|vatandasimiz|vatandaslarimiz|tsk/.test(text);
 const foreign=/\b(?:israil|gazze|filistin|iran|ukrayna|rusya|abd|amerika|pakistan|hindistan|afganistan|suriye|irak|katar|azerbaycan|yunanistan|almanya|fransa|lubnan)\b/.test(h);
 const titleCity=TURKEY_CITIES.some(c=>new RegExp('(?:^| )'+c+'(?:da|de|dan|den|nin|nun)?(?: |$)').test(h));
 const connected=!!(city||explicitTurkey)&&(!foreign||linkedAbroad||titleCity),location=city?city.toLocaleUpperCase('tr-TR'):(foreign&&linkedAbroad?'Türkiye bağlantılı yurt dışı':'Türkiye geneli');
 const no={nationalCritical:false,nationalCategory:null,nationalReason:null,nationalLocation:null,nationalKeywords:[]};
 const exerciseOnly=/tatbikat/.test(h)&&!/(?:helikopter|ucag|ucak).{0,45}(?:dustu|kaza kirim)|(?:asker|polis|personel).{0,25}sehit oldu/.test(h);
 if(!connected||exerciseOnly||/senaryo|simulasyon|belgesel|film|dizi|anma toren|yil donum|yildonum|yillar once|tarihte bugun|arsiv goruntu|\banma\b|\banildi\b|\baniliyor\b|sehitler anildi|sehit.*(?:hatirasi|adinin verildigi)|bomba transfer|saldiri(?:si)? (?:plani )?(?:engellendi|onlendi)|model ucak|maket ucak|oyuncak ucak|olasi deprem|deprem riski|deprem egitimi|sehit (?:yok|olmadi)|iddia(?:si)? (?:asilsiz|yalan)/.test(h))return no;
 const dead=casualtyCount(text,'dead'),injured=casualtyCount(text,'injured'),evacuated=casualtyCount(text,'evacuated'),mass=dead>=5||injured>=20||/cok sayida (?:olu|kisi hayatini|kisi yaralandi)|cok sayida can kaybi/.test(text),deaths=(dead>=1||/hayatini kaybetti|yasamini yitirdi|\bolu\b/.test(text))&&!/can kaybi (?:yok|olmadi|yasanmadi)|olen yok/.test(text);
 let group=-1,reason='';
 if(/sehit (?:ol|dus|ver)|(?:asker|polis|jandarma|personel).{0,25}sehit|sehit sayisi|(?:[0-9]+|bir|iki|uc|dort|bes|alti|yedi|sekiz|dokuz|on) sehit/.test(h)&&/asker|polis|jandarma|personel|tsk|msb|sehitlerimiz/.test(text)){group=1;reason='Yeni şehit/kamu güvenliği personeli kaybı bildirimi';}
 else if(/helikopter|ucak|ucag|f ?16/.test(h)&&/dustu|dusuruldu|kaza|kirim|irtibat.{0,15}kesildi|kayboldu/.test(h)){group=0;reason='Türkiye bağlantılı hava aracı kazası veya irtibat kaybı';}
 else if(/teror saldirisi|bombali saldiri|intihar saldirisi|canli bomba|roketli saldiri|fuzeli saldiri|kitlesel saldiri/.test(h)){group=2;reason='Türkiye bağlantılı büyük saldırı bildirimi';}
 else if(/silahli saldiri|ates acti|silahli baskin/.test(h)&&(dead>=3||injured>=10||/askeri (?:tesis|us)|buyukelcilik|konsolosluk/.test(h)&&deaths)){group=2;reason='Can kaybı/yaralı sayısı veya hedefi nedeniyle yüksek etkili saldırı';}
 else if(/patlama|patladi|kimyasal sizinti|radyasyon sizinti/.test(h)&&(dead>=3||injured>=10||/muhimmat|rafineri|maden/.test(h)&&deaths||evacuated>=100)){group=3;reason='Kayıp, etkilenen kişi sayısı veya kritik tesis bağlamıyla büyük patlama/sızıntı';}
 else if(/deprem|tsunami/.test(h)&&!(/deprem/.test(h)&&/beklen|olabilir|olacak|uzman|ongoru|hazirlik/.test(h))){const magnitude=Number((text.match(/(?:^| )(\d[.,]\d)\s*(?:buyuklugunde|siddetinde)/)||[])[1]?.replace(',','.'));if(magnitude>=5.5||magnitude>=5&&/yikil|enkaz|hayatini kaybet|can kaybi/.test(text)||/tsunami uyarisi|yikici deprem/.test(h)){group=4;reason='Deprem büyüklüğü, yıkım veya tsunami uyarısı nedeniyle kritik afet';}}
 else if(/yangin|sel|taskin|heyelan|cig|baraj/.test(h)&&(dead>=3||injured>=20||evacuated>=100||/afet bolgesi|birden fazla il|yerlesim yerleri tahliye|ilceler tahliye|tahliye karari/.test(text))){group=4;reason='Çoklu can kaybı, yaygın etki veya toplu tahliye içeren afet';}
 else if(/otobus|tren|feribot|gemi|yolcu teknesi|zincirleme kaza/.test(h)&&/kaza|devril|carpis|raydan|batti|alabora/.test(h)&&mass){group=5;reason='Toplu ulaşım/deniz kazasında yüksek kayıp veya yaralı sayısı';}
 else if(/gocuk|gocug|coktu|cokme|maden kazasi/.test(h)&&(dead>=3||injured>=10||evacuated>=5)){group=3;reason='Göçük/çökmede çoklu kayıp veya mahsur kalan kişi bildirimi';}
 else if(/ulusal yas ilan|ulusal acil durum|saglik acil durumu|ulke genelinde.{0,30}(?:elektrik|kesinti|siber)|birden fazla ilde.{0,30}(?:kesinti|kimyasal)|kritik altyapiya saldiri|acil halk sagligi uyarisi/.test(h)||/toplu zehirlenme/.test(h)&&injured>=50){group=6;reason='Ülke genelini veya çok sayıda kişiyi etkileyen kritik durum';}
 if(group<0)return no;const profile=NATIONAL_KEYWORD_GROUPS[group],matched=profile.terms.filter(term=>text.includes(nationalText(term)));
 const followup=/gozalti|tutuklu|tutuklandi|sorusturma|iddianame|yargilan|mahkeme|cenaze|son gorev|son yolculuk|ugurlandi|ugurlama|ailesine taziye|topraga verildi|defnedildi/.test(h);
 return {nationalCritical:true,nationalUrgent:!followup,nationalPhase:followup?'Olayın devamındaki gelişme':'Olay bildirimi',nationalCategory:profile.name.replace('Ulusal · ',''),nationalReason:reason+(followup?' · Olayın devamındaki gelişme':'')+'; otomatik ön eleme, insan incelemesi gerekir.',nationalLocation:location,nationalKeywords:matched.slice(0,12)};
}
function sourceSignals(source,title,description='',url=''){
 let local=relevance(title,description,source.profile);if(!local.relevant&&url){try{const path=relevance(new URL(url,source.url).pathname.replace(/[-_]/g,' '),'',source.profile);if(path.relevant)local={...path,matchReason:'Yayın bağlantısında ilçe/kamu görevi eşleşti'}}catch{}}const national=source.national?nationalCritical(title,description):{nationalCritical:false};
 return {...local,...national,relevant:local.relevant||national.nationalCritical,scope:local.relevant?'local':national.nationalCritical?'national':'unrelated',...(national.nationalCritical?{priority:'review',priorityReason:national.nationalReason}:{}),...(national.nationalCritical&&!local.relevant?{topic:'Ulusal kritik',neighborhood:'Türkiye geneli',locationBasis:'Ulusal/Türkiye bağlantılı yayın; il adı kaynak metninden otomatik çıkarılır.',matchedKeywords:national.nationalKeywords,matchedGroups:['Ulusal kritik · '+national.nationalCategory],matchReason:national.nationalReason}:{})};
}

const MIGRATION_TABLES=['workspace_settings','team_accounts','members','snapshots','case_records','case_history','alert_log','alert_reads','briefings','personal_records','personal_activity','audit'];
async function migrationExport(request,env,user,url){
 if(!await adminSession(request,env,user))return json({error:'Yönetici girişi gerekli'},401);
 if(request.method!=='POST'||request.headers.get('Origin')!==url.origin)return json({error:'İstek kaynağı reddedildi'},403);
 const rows=await env.DB.batch(MIGRATION_TABLES.map(t=>env.DB.prepare('SELECT * FROM '+t)));
 const tables=Object.fromEntries(MIGRATION_TABLES.map((t,i)=>[t,rows[i].results||[]]));
 await auditStatement(env,user,'Sunucu aktarım yedeği oluşturuldu','Hesaplar ve kayıtlar; oturumlar hariç').run();
 return json({format:'umraniye-osint-transfer-v1',createdAt:new Date().toISOString(),tables},200,{'Content-Disposition':'attachment; filename="umraniye-osint-transfer.json"'});
}

async function unifiedLogin(request,env,url){
 if(request.method!=='POST'||request.headers.get('Origin')!==url.origin)return json({error:'İstek reddedildi'},403);
 let body;try{body=await readBody(request.clone(),4096)}catch{return json({error:'Geçersiz giriş isteği'},400)}
 const administrator=typeof body.username==='string'&&body.username.normalize('NFC')===env.OSINT_ADMIN_USERNAME?.normalize('NFC');
 return administrator?passwordAction(request,env,identity(request,env),new URL('/api/admin/login',url)):teamLogin(request,env,new URL('/api/team/login',url));
}
async function unifiedLogout(request,env,url){
 if(request.method!=='POST'||request.headers.get('Origin')!==url.origin)return json({error:'İstek reddedildi'},403);
 const statements=[],a=cookieToken(request),t=teamToken(request);
 if(a)statements.push(env.DB.prepare('DELETE FROM admin_sessions WHERE token_hash=?').bind(await adminTokenDigest(a,env)));
 if(t)statements.push(env.DB.prepare('DELETE FROM team_sessions WHERE token_hash=?').bind(await sha(t)));
 if(statements.length)await env.DB.batch(statements);
 const response=json({ok:true});response.headers.append('Set-Cookie',clearAdminCookie);response.headers.append('Set-Cookie','__Host-osint_team=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0');return response;
}
async function serviceCanRead(request,env){const token=request.headers.get('X-OSINT-Service-Key');return !!(token&&env.OSINT_AUTOMATION_KEY_SHA256&&await equalSecret(await sha(token),env.OSINT_AUTOMATION_KEY_SHA256))}

const application = {
  async fetch(request,env={},ctx){
    const url=new URL(request.url);let user=identity(request,env);
    if(cookieToken(request)&&await adminSession(request,env,user))user={id:ADMIN_PRINCIPAL,email:env.OSINT_ADMIN_EMAIL||null,admin:true};
    if(url.pathname==='/api/login')return unifiedLogin(request,env,url);
    if(url.pathname==='/api/logout')return unifiedLogout(request,env,url);
    if(url.pathname.startsWith('/api/team/')){try{return await teamLogin(request,env,url)}catch{return json({error:'Giriş isteği tamamlanamadı'},400)}}
    if(url.pathname.startsWith('/api/account')){try{return await accountAPI(request,env,user,url)}catch{return json({error:'Hesap işlemi tamamlanamadı. Yeniden deneyin.'},400)}}
    if(url.pathname==='/giris')return await accountActor(request,env,user)?Response.redirect(url.origin+'/?view=account',302):htmlResponse(TEAM_LOGIN_HTML);
    if(url.pathname==='/ekip')return htmlResponse(await workspaceActor(request,env,user)?WORKSPACE_HTML:TEAM_LOGIN_HTML);
    if(url.pathname.startsWith('/api/workspace')){try{return await workspaceAPI(request,env,user,url)}catch(e){return json({error:'İşlem tamamlanamadı. Alanları kontrol edip yeniden deneyin.'},400)}}
    const privateRoute=['/','/index.html','/yeni-tasarim','/api/config','/api/refresh'].includes(url.pathname)||url.pathname.startsWith('/api/public/')||url.pathname.startsWith('/assets/briefing')||url.pathname.startsWith('/assets/jspdf');
    if(privateRoute&&!await workspaceActor(request,env,user)&&!(url.pathname==='/api/config'&&await serviceCanRead(request,env)))return url.pathname.startsWith('/api/')||url.pathname.startsWith('/assets/')?json({error:'Kullanıcı girişi gerekli'},401):Response.redirect(url.origin+'/giris',302);
    if(url.pathname==='/assets/briefing-pdf.js')return new Response(BRIEFING_JS,{headers:{'Content-Type':'application/javascript; charset=utf-8','Cache-Control':'private,max-age=86400','X-Content-Type-Options':'nosniff'}});
    if(url.pathname==='/api/public/export'){const data=await publishedData(env);return new Response(eventsCSV(reportEvents(data.events,url)),{headers:{'Content-Type':'text/csv; charset=utf-8','Content-Disposition':'attachment; filename=Umraniye_OSINT.csv'}})}
    if(url.pathname==='/api/public/map')return json(MAP_DATA);
    if(url.pathname==='/api/refresh')return publicRefresh(request,env,ctx,url);
    if(url.pathname==='/mcp')return mcp(request,env,ctx,user,url);
    if(url.pathname==='/api/automation/refresh')return serviceUpdate(request,env,ctx,url);
    if(url.pathname==='/api/automation/instructions')return json({revision:'auto-refresh-v1',intervalMinutes:10,totalBatches:Math.ceil(activeSources(await workspaceSettings(env)).length/5),instructions:'Bu Site için get_site ile güncel siwc_bypass_bearer_token değerini alın. Yalnız bu Siteye OAI-Sites-Authorization: Bearer ve X-OSINT-Service-Key başlıklarında gönderin; günlük, mesaj, dosya veya görev metnine yazmayın. 0 ile totalBatches-1 arasındaki her grup için POST /api/automation/refresh?batch=N isteğini sırayla çalıştırın. Her grup sonucunu kontrol edin. Geçici hatada en fazla bir kez yeniden deneyin. Sonunda GET /api/config ile kalıcı syncedAt ve kaynak sonuçlarını doğrulayın. Yeniden yayınlama veya yönetici giriş bilgileri gerekmez.'});
    if(url.pathname==='/yonetim'||url.pathname==='/yonetim/ekip')return await adminSession(request,env,user)?htmlResponse(ADMIN_HTML):loginPage(user);
    if(['/api/admin/login','/api/admin/logout'].includes(url.pathname)){try{return await passwordAction(request,env,user,url)}catch{return json({error:'Giriş işlemi tamamlanamadı. Yeniden deneyin.'},503)}}
    if(url.pathname==='/api/admin/migration-export')return migrationExport(request,env,user,url);
    if(url.pathname.startsWith('/api/admin/')){try{return await adminAPI(request,env,user,url)}catch{return json({error:'Yönetim verisi okunamadı. Yeniden deneyin.'},503)}}
    if(url.pathname==='/api/session'){
      let member=false;
      if(user.id&&user.email&&env.DB){const m=await env.DB.prepare('SELECT active,user_id FROM members WHERE email=?').bind(user.email).first();member=!!(m?.active&&(!m.user_id||m.user_id===user.id));if(member&&!m.user_id)await env.DB.prepare('UPDATE members SET user_id=? WHERE email=? AND user_id IS NULL').bind(user.id,user.email).run();}
      const session=await adminSession(request,env,user);
      return json({email:user.email,admin:user.admin,member,adminUnlocked:!!session,adminExpiresAt:session?.expires_at||null});
    }
    if(url.pathname==='/assets/umraniye-kaymakamligi-logo.png'||url.pathname==='/favicon.png')return new Response(Uint8Array.from(atob(LOGO_BASE64),c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/png','Cache-Control':'public,max-age=86400','X-Content-Type-Options':'nosniff'}});
    if(url.pathname==='/api/config'){const data=await publishedData(env);return json({neighborhoods:NEIGHBORHOODS,version:'1.0',nationalCategories:NATIONAL_KEYWORD_GROUPS.map(g=>g.name.replace('Ulusal · ','')),retention:{months:2,cutoff:retentionCutoff()},schedule:env.OSINT_AUTO_UPDATE_ENABLED==='true',refreshIntervalMs:600000,totalBatches:Math.ceil(activeSources(await workspaceSettings(env)).length/5),initialData:{events:data.events,syncedAt:data.syncedAt}});}
    if(url.pathname==='/api/sync'){
      if(request.method!=='POST')return json({error:'POST gerekli'},405,{'Allow':'POST'});
      if(request.headers.get('Origin')&&request.headers.get('Origin')!==url.origin)return json({error:'İstek kaynağı reddedildi'},403);
      if(!user.admin)return json({error:'Yalnız yönetici kaynak yenileyebilir'},user.id?403:401);
      if(request.headers.get('Origin')!==url.origin)return json({error:'İstek kaynağı gerekli'},403);
      if(!env.DB)return json({error:'Ortak veritabanı bağlı değil'},503);
      if(!await adminSession(request,env,user))return json({error:'Yönetici şifresiyle giriş gerekli'},401);
      const batch=Number(url.searchParams.get('batch')||0);if(!Number.isInteger(batch)||batch<0||batch>=Math.ceil(SOURCES.length/5))return json({error:'Geçersiz kaynak grubu'},400);
      return json(await syncBatch(batch,env,ctx,url.origin,user));
    }
    if(url.pathname==='/health')return json({ok:true,service:'umraniye-osint',version:'0.1'});
    if(url.pathname.startsWith('/api/'))return json({error:'Bulunamadı'},404);
    if(url.pathname==='/yeni-tasarim')return Response.redirect(url.origin+'/',308);
    if(!['/','/index.html'].includes(url.pathname))return new Response('Bulunamadı',{status:404});
    return new Response(APP_HTML,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','Permissions-Policy':'camera=(), microphone=(), geolocation=()','Content-Security-Policy':"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'self' https://chatgpt.com https://*.chatgpt.com"}});
  }
};

export default {async fetch(request,env={},ctx){
 const url=new URL(request.url);
 if(!['GET','HEAD','POST'].includes(request.method))return json({error:'Yöntem desteklenmiyor'},405,{'Allow':'GET, HEAD, POST'});
 if(request.method==='POST'&&request.headers.get('Sec-Fetch-Site')==='cross-site')return json({error:'İstek kaynağı reddedildi'},403);
 const response=await application.fetch(request,env,ctx),headers=new Headers(response.headers);
 headers.set('X-Content-Type-Options','nosniff');headers.set('Referrer-Policy','no-referrer');headers.set('Permissions-Policy','camera=(), microphone=(), geolocation=()');
 if(url.protocol==='https:')headers.set('Strict-Transport-Security','max-age=31536000');
 return new Response(response.body,{status:response.status,headers});
}};
